import pandas as pd
import numpy as np
import plotly.graph_objects as go
import plotly.express as px
from plotly.subplots import make_subplots
import jinja2
import os

# 1. Load and prepare data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Daily_Return'] = df['Close'].pct_change()

# 2. Calculate KPIs
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
start_date = df['Date'].iloc[0]
end_date = df['Date'].iloc[-1]
years = (end_date - start_date).days / 365.25

cumulative_return = (end_price / start_price) - 1
cagr = (end_price / start_price) ** (1 / years) - 1

df['Peak'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Peak']) / df['Peak']
max_drawdown = df['Drawdown'].min()

annualized_volatility = df['Daily_Return'].std() * np.sqrt(252)
avg_daily_volume = df['Volume'].mean()

# High-Low Spread
df['Spread'] = df['High'] - df['Low']
df['Spread_Pct'] = df['Spread'] / df['Close']

# Annual performance
df['Year'] = df['Date'].dt.year
annual_returns = df.groupby('Year').apply(
    lambda x: (x['Close'].iloc[-1] / x['Close'].iloc[0]) - 1,
    include_groups=False
).reset_index(name='Annual_Return')

# Decade performance
df['Decade'] = (df['Year'] // 10) * 10
decade_returns = df.groupby('Decade').apply(
    lambda x: (x['Close'].iloc[-1] / x['Close'].iloc[0]) - 1,
    include_groups=False
).reset_index(name='Decade_Return')

# 3. Generate Charts
# Chart 1: Price Trend & Volume Subplot
fig_price = make_subplots(specs=[[{"secondary_y": True}]])
fig_price.add_trace(go.Scatter(x=df['Date'], y=df['Close'], name='Close Price', line=dict(color='#2c3e50', width=1.5)), secondary_y=False)

# Add 200 SMA
df['SMA_200'] = df['Close'].rolling(window=200).mean()
fig_price.add_trace(go.Scatter(x=df['Date'], y=df['SMA_200'], name='200-Day SMA', line=dict(color='#e74c3c', width=1)), secondary_y=False)

fig_price.add_trace(go.Bar(x=df['Date'], y=df['Volume'], name='Volume', marker_color='rgba(149, 165, 166, 0.3)'), secondary_y=True)

fig_price.update_layout(
    title='Nike (NKE) Long-Term Price Trend & Trading Volume',
    xaxis_title='Date',
    yaxis_title='Price (USD)',
    yaxis2_title='Volume',
    plot_bgcolor='white',
    hovermode='x unified',
    margin=dict(l=40, r=40, t=60, b=40),
    legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1)
)
fig_price.update_yaxes(showgrid=True, gridcolor='#f0f0f0', secondary_y=False)
fig_price.update_yaxes(showgrid=False, secondary_y=True)
html_fig_price = fig_price.to_html(full_html=False, include_plotlyjs='cdn')

# Chart 2: Drawdown Over Time
fig_dd = go.Figure()
fig_dd.add_trace(go.Scatter(x=df['Date'], y=df['Drawdown'], fill='tozeroy', name='Drawdown', line=dict(color='#c0392b', width=1)))
fig_dd.update_layout(
    title='Historical Drawdowns from All-Time Highs',
    xaxis_title='Date',
    yaxis_title='Drawdown (%)',
    yaxis_tickformat='.0%',
    plot_bgcolor='white',
    margin=dict(l=40, r=40, t=60, b=40)
)
fig_dd.update_yaxes(showgrid=True, gridcolor='#f0f0f0')
html_fig_dd = fig_dd.to_html(full_html=False, include_plotlyjs=False)

# Chart 3: Annual Returns
fig_ann = go.Figure()
colors = ['#27ae60' if val > 0 else '#e74c3c' for val in annual_returns['Annual_Return']]
fig_ann.add_trace(go.Bar(x=annual_returns['Year'], y=annual_returns['Annual_Return'], marker_color=colors, text=[f"{val:.1%}" for val in annual_returns['Annual_Return']], textposition='outside'))
fig_ann.update_layout(
    title='Annual Performance (Year-Over-Year Return)',
    xaxis_title='Year',
    yaxis_title='Return (%)',
    yaxis_tickformat='.0%',
    plot_bgcolor='white',
    margin=dict(l=40, r=40, t=60, b=40)
)
fig_ann.update_yaxes(showgrid=True, gridcolor='#f0f0f0')
html_fig_ann = fig_ann.to_html(full_html=False, include_plotlyjs=False)

# Chart 4: Rolling Volatility (252-day)
df['Rolling_Vol'] = df['Daily_Return'].rolling(window=252).std() * np.sqrt(252)
fig_vol = go.Figure()
fig_vol.add_trace(go.Scatter(x=df['Date'], y=df['Rolling_Vol'], name='252-Day Rolling Volatility', line=dict(color='#8e44ad', width=1.5)))
fig_vol.update_layout(
    title='Annualized Rolling Volatility (252-Day)',
    xaxis_title='Date',
    yaxis_title='Volatility',
    yaxis_tickformat='.1%',
    plot_bgcolor='white',
    margin=dict(l=40, r=40, t=60, b=40)
)
fig_vol.update_yaxes(showgrid=True, gridcolor='#f0f0f0')
html_fig_vol = fig_vol.to_html(full_html=False, include_plotlyjs=False)

# 4. Synthesize textual insights
best_year = annual_returns.loc[annual_returns['Annual_Return'].idxmax()]
worst_year = annual_returns.loc[annual_returns['Annual_Return'].idxmin()]
ath_price = df['Close'].max()
ath_date = df.loc[df['Close'].idxmax(), 'Date']
atl_price = df['Close'].min()
atl_date = df.loc[df['Close'].idxmin(), 'Date']

